<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {usePhasePage} from '../phasePage'
import {usePhaseThreeText} from '../phaseThreeText'
import {dateRangeValid,monthEnd} from '../timekeepingUi'
import {addDays,storeToday,hours} from '../time'
import type {SummaryRow} from '../phaseThreeTypes'
import PhaseStatus from '../components/PhaseStatus.vue'
const {api,home,t,p,base,loading,failure,load}=usePhasePage(),{q}=usePhaseThreeText(),from=ref(storeToday().slice(0,8)+'01'),to=ref(monthEnd(from.value)),companyId=ref(''),items=ref<SummaryRow[]>([])
const totals=computed(()=>items.value.reduce((a,v)=>({schedules:a.schedules+v.schedules,approved:a.approved+v.approved,pending:a.pending+v.pending,workSeconds:a.workSeconds+v.workSeconds,paidLeaveSeconds:a.paidLeaveSeconds+v.paidLeaveSeconds,unpaidLeaveSeconds:a.unpaidLeaveSeconds+v.unpaidLeaveSeconds}),{schedules:0,approved:0,pending:0,workSeconds:0,paidLeaveSeconds:0,unpaidLeaveSeconds:0}))
function refresh(){if(!home.value?.employeeManage){failure.value=p('noAccess');return}if(!dateRangeValid(from.value,to.value)){failure.value=p('invalid');return}if(companyId.value&&!home.value.headOffice){failure.value=p('noAccess');return}items.value=[];void load(()=>api().get<{items:SummaryRow[]}>(`/work-summary?from=${from.value}&to=${to.value}${companyId.value?'&companyId='+encodeURIComponent(companyId.value):''}`),v=>items.value=v.items)}
onMounted(refresh)
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{q('summary')}}</h2><RouterLink :to="base+'/approvals'">{{q('approvals')}}</RouterLink></header><form v-if="home?.employeeManage" class="wf-filters" @submit.prevent="refresh"><label>{{p('from')}}<input v-model="from" required type="date"></label><label>{{p('to')}}<input v-model="to" required type="date" :min="from" :max="addDays(from,30)"></label><label v-if="home.headOffice">{{q('scope')}}<select v-model="companyId"><option value="">{{q('thisStore')}}</option><option v-for="c in home.companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button :disabled="loading">{{p('filter')}}</button></form><PhaseStatus :failure="failure" :loading="loading"/><div v-if="!loading&&home?.employeeManage" class="wf-table-wrap"><table><thead><tr><th>{{p('employee')}}</th><th>{{q('company')}}</th><th>{{q('store')}}</th><th>{{q('scheduled')}}</th><th>{{q('approvedCount')}}</th><th>{{q('pendingCount')}}</th><th>{{q('work')}}</th><th>{{q('paidLeave')}}</th><th>{{q('unpaidLeave')}}</th></tr></thead><tbody><tr v-for="r in items" :key="r.employeeId+':'+r.companyId+':'+r.storeId"><td>{{r.employeeName}}</td><td>{{home?.companies.find(c=>c.id===r.companyId)?.name||r.companyId}}</td><td>{{r.storeName}}</td><td>{{r.schedules}}</td><td>{{r.approved}}</td><td>{{r.pending}}</td><td>{{hours(r.workSeconds)}}</td><td>{{hours(r.paidLeaveSeconds)}}</td><td>{{hours(r.unpaidLeaveSeconds)}}</td></tr><tr v-if="!items.length"><td colspan="9" class="wf-empty">{{t('empty')}}</td></tr></tbody><tfoot v-if="items.length"><tr><th colspan="3">{{q('total')}}</th><th>{{totals.schedules}}</th><th>{{totals.approved}}</th><th>{{totals.pending}}</th><th>{{hours(totals.workSeconds)}}</th><th>{{hours(totals.paidLeaveSeconds)}}</th><th>{{hours(totals.unpaidLeaveSeconds)}}</th></tr></tfoot></table></div><p class="wf-hint">{{q('summaryHint')}}</p></section></template>
